<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import {Session} from '$lib/stores';
 import {createStaffClient,type StaffClient} from './staff-client';
 let {reportId}:{reportId:string}=$props();let client:StaffClient|undefined,epoch=0,closed=false;
 let history=$state<any>(),pending=$state(false),error=$state(''),reason=$state(''),review=$state(false),notice=$state(''),opened=$state(false),unknown=$state(false);
 const path=$derived('/my/reports/'+encodeURIComponent(reportId)+'/appeal');
 function guard(){const generation=epoch,id=reportId,session=$Session;return()=>{if(closed||generation!==epoch||id!==reportId||session!==$Session)throw Error('This report view changed. Open it again.');};}
 $effect(()=>{const id=reportId,session=$Session;untrack(()=>{epoch++;client?.dispose();client=undefined;history=undefined;pending=false;error='';reason='';review=false;notice='';opened=false;unknown=false;});});
 onDestroy(()=>{closed=true;epoch++;client?.dispose();});
 async function load(){if(pending||!$Session?.identity?.id)return;const assert=guard();opened=true;pending=true;error='';try{const selected=client??await createStaffClient($Session.identity.id,assert);assert();client=selected;const result=await selected.read('/my/reports/'+encodeURIComponent(reportId)+'/history');assert();if(result.scope!=='personal-report-history'||result.id!==reportId||!Array.isArray(result.data))throw Error('The report history could not be checked.');history=result;unknown=!!selected.pending(path);}catch(cause){try{assert();history=undefined;error=cause instanceof Error?cause.message:'The report history could not be loaded.';}catch{}}finally{try{assert();pending=false;}catch{}}}
 async function appeal(){if(!client||!history||pending||!review||!reason.trim())return;const assert=guard();pending=true;error='';try{await client.mutate(path,{version:history.version,reason});assert();review=false;reason='';notice='Your appeal was saved for moderator review.';unknown=false;}catch(cause){try{assert();unknown=!!client.pending(path);error=cause instanceof Error?cause.message:'The appeal was not confirmed.';}catch{}}finally{try{assert();pending=false;}catch{}}if(!unknown)await load();}
 async function reconcile(){if(!client||pending)return;const assert=guard();pending=true;error='';try{await client.reconcile(path);assert();unknown=false;review=false;notice='Your earlier appeal was confirmed.';}catch(cause){try{assert();error='No confirmed receipt is available yet. Do not submit again; ask the instance moderator to check this report.';}catch{}}finally{try{assert();pending=false;}catch{}}if(!unknown)await load();}
</script>
<section class="space-y-3" aria-label="Personal report history">
 <button class="rounded border p-2" disabled={pending} onclick={load}>{opened?'Refresh decision history':'Decision history and appeal'}</button>
 {#if pending}<p role="status">Checking your report…</p>{/if}{#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if history}<ol class="space-y-2">{#each history.data as row}<li class="border-l-2 pl-3"><strong>{row.operation==='correct'?'Local decision corrected':row.operation==='appeal'?'Appeal submitted':row.operation==='reopen'?'Report reopened':row.operation==='create'?'Report submitted':row.operation==='accept'?'Report accepted':'Report refused'}</strong> · {new Date(row.createdAt).toLocaleString()}{#if row.reason}<p class="whitespace-pre-wrap">{row.reason}</p>{/if}</li>{/each}</ol>
  {#if history.appealState==='pending'}<p>Your appeal is awaiting review.</p>{:else if history.status!=='waiting'&&!unknown}<form class="space-y-2" onsubmit={event=>{event.preventDefault();review=true;}}><label>Why should this decision be reviewed?<textarea class="block w-full rounded border p-2" rows="3" maxlength="4000" bind:value={reason} disabled={pending||review}></textarea></label>{#if review}<p>Submit this explanation to the instance’s moderation team. An appeal does not automatically restore content or change group leadership.</p><button type="button" class="rounded border p-2" disabled={pending} onclick={()=>review=false}>Cancel</button> <button type="button" class="rounded border p-2" disabled={pending||!reason.trim()} onclick={appeal}>Submit appeal</button>{:else}<button class="rounded border p-2" disabled={pending||!reason.trim()}>Review appeal</button>{/if}</form>{/if}
 {/if}
 {#if unknown}<p>Your earlier appeal has an unconfirmed outcome. It will not be repeated automatically.</p><button class="rounded border p-2" disabled={pending} onclick={reconcile}>Check appeal receipt</button>{/if}
</section>
